var blocks = NotionMarkdownImporter.Import(markdown, pageId);
var blockService = new NotionEditorBlockService(AggregateProvider);

// The complete imported tree is persisted through one aggregate save.
await blockService.CreateBlocksAsync(pageId.ToString(), blocks, afterBlockId: null);

const string markdown = """
    | Name | Status |
    | :--- | ---: |
    | CF26 | Ready |
    """;

var blocks = NotionMarkdownImporter.Import(markdown, pageId);

var table = blocks.Single(b => b.Type == BlockType.Table);
var rows  = blocks.Where(b => b.Type == BlockType.TableRow).ToList();

// rows are children of the table, never orphans
Assert.All(rows, r => Assert.Equal(table.Id, r.ParentBlockId));

var content = (ITableBlockContent)table.Content;
// [Left, Right]
var alignments = content.ColumnAlignments;

// raw markup is encoded, unsafe schemes lose the link
NotionMarkdownImporter.InlineMarkdownToHtml("<img src=x onerror=alert(1)>");
// → "&lt;img src=x onerror=alert(1)&gt;"

NotionMarkdownImporter.InlineMarkdownToHtml("[click](javascript:alert(1))");
// → "click"   (no <a href>)

NotionMarkdownImporter.InlineMarkdownToHtml("[ok](https://example.test)");
// → "<a href=\"https://example.test\">ok</a>"
